find_circles <- function(node, path="") {
  out <- NULL
  nm <- xml2::xml_name(node)
  id <- xml2::xml_attr(node, "id")
  if (nm == "circle") {
    out <- data.frame(path=path, id=id, cx=xml2::xml_attr(node,"cx"),
                      cy=xml2::xml_attr(node,"cy"), r=xml2::xml_attr(node,"r"))
  }
  kids <- xml2::xml_children(node)
  for (k in kids) {
    out <- rbind(out, find_circles(k, paste0(path, "/", ifelse(is.na(id), nm, id))))
  }
  out
}
