l <- xml2::read_xml("figure.svg")
get_all_circles <- function(node, parent=NA, idx=0) {
  out <- NULL
  nm <- xml2::xml_name(node)
  id <- xml2::xml_attr(node, "id")
  if (nm == "circle") {
    out <- data.frame(idx=idx, parent=parent, cx=xml2::xml_attr(node,"cx"),
                      cy=xml2::xml_attr(node,"cy"))
  }
  kids <- xml2::xml_children(node)
  for (k in kids) {
    idx <- idx + 1
    newparent <- if (!is.na(id) && grepl("geom_point", id)) id else parent
    out <- rbind(out, get_all_circles(k, newparent, idx))
  }
  out
}
